(function(){'use strict';var P='bm_salesproof_';var SEL=['#price_display','.js-price-display','.product-prices','.product-price','[data-price]','.price'];var MAXW=6000,POLL=200;function hc(s){var h=0;for(var i=0;i<s.length;i++){h=(h<<5)-h+s.charCodeAt(i);h|=0;}return Math.abs(h);}function si(s,mn,mx){return mn+(hc(s)%(mx-mn+1));}function pk(){return location.pathname.replace(/\/$/,'');}function mk(){var d=new Date();return d.getFullYear()+'-'+(d.getMonth()+1);}function hk(){var d=new Date();return d.getFullYear()+'-'+d.getMonth()+'-'+d.getDate()+'-'+Math.floor(d.getHours()/3);}function st(k){return{s:si(k+mk(),14,68),c:si(k+hk(),1,7)};}function fp(){for(var i=0;i<SEL.length;i++){var e=document.querySelector(SEL[i]);if(e)return e;}return null;}function css(){if(document.getElementById(P+'style'))return;var s=document.createElement('style');s.id=P+'style';s.textContent='.'+P+'bar{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0 2px}.'+P+'item{display:flex;align-items:center;gap:5px;font-size:12.5px;font-weight:600;padding:4px 10px;border-radius:20px}.'+P+'dot{width:6px;height:6px;border-radius:50%;display:inline-block;flex:none}.'+P+'sold{color:#1E7A4A;background:rgba(30,122,74,0.09)}.'+P+'sold .'+P+'dot{background:#1E7A4A}.'+P+'cart{color:#1D5FA8;background:rgba(47,65,87,0.09)}.'+P+'cart .'+P+'dot{background:#1D5FA8}';document.head.appendChild(s);}function rd(){if(document.querySelector('.'+P+'bar'))return true;var pe=fp();if(!pe)return false;var d=st(pk());var b=document.createElement('div');b.className=P+'bar';b.innerHTML='<span class="'+P+'item '+P+'sold"><span class="'+P+'dot"></span>Vendido '+d.s+' veces este mes</span><span class="'+P+'item '+P+'cart"><span class="'+P+'dot"></span>'+d.c+(d.c===1?' persona lo tiene':' personas lo tienen')+' en el carrito ahora</span>';pe.insertAdjacentElement('afterend',b);return true;}function isPP(){return document.body.classList.contains('template-product');}function init(){if(!isPP())return;css();var w=0,t=setInterval(function(){if(rd()||w>=MAXW)clearInterval(t);w+=POLL;},POLL);}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();